// Build a valid qoi_desc and pixel buffer matching constraints, then write to a fuzz-file
// Choose channels in {3,4}
unsigned int rnd = *FUZZ_PARAM(unsigned int);
unsigned int channels = (rnd & 1) ? 3u : 4u;
// Limit total bytes to <= 2048 for performance and ensure width,height >=1
unsigned int w = ((*FUZZ_PARAM(unsigned int)) % 64u) + 1u;
unsigned int h = ((*FUZZ_PARAM(unsigned int)) % 64u) + 1u;
unsigned int max_h_from_budget = 2048u / (w * channels);
if (max_h_from_budget == 0u) { max_h_from_budget = 1u; }
if (h > max_h_from_budget) { h = max_h_from_budget; }
// Enforce QOI image size constraint width*height < 400,000,000 (trivially true with our caps)
unsigned int colorspace = ((*FUZZ_PARAM(unsigned int)) & 1u);
qoi_desc desc_local; desc_local.width = w; desc_local.height = h; desc_local.channels = (unsigned char)channels; desc_local.colorspace = (unsigned char)colorspace;
// Create pixel buffer exactly width*height*channels bytes
size_t px_count = (size_t)w * (size_t)h * (size_t)channels;
std::string pixels = FUZZ_PARAM_STR();
if (pixels.size() < px_count) { pixels.resize(px_count, '\0'); }
else if (pixels.size() > px_count) { pixels.resize(px_count); }
// filename must be writable; the fuzzer runtime provides a valid temporary path
const char *path = FUZZ_PARAM_FILENAME();
int written = qoi_write(path, (const void*)pixels.data(), (const qoi_desc*)&desc_local);
// If our constructed parameters are valid yet write failed, that's allowed (I/O/alloc failure => 0).
// No persistent outputs; nothing to free here.

// Prepare a valid QOI file by encoding and writing a small image, then read it back
// Construct a tiny valid image buffer
unsigned int channels = ((*FUZZ_PARAM(unsigned int)) & 1u) ? 3u : 4u;
unsigned int w = ((*FUZZ_PARAM(unsigned int)) % 32u) + 1u;
unsigned int h = ((*FUZZ_PARAM(unsigned int)) % 32u) + 1u;
unsigned int max_h_from_budget = 2048u / (w * channels);
if (max_h_from_budget == 0u) { max_h_from_budget = 1u; }
if (h > max_h_from_budget) { h = max_h_from_budget; }
unsigned int colorspace = ((*FUZZ_PARAM(unsigned int)) & 1u);
qoi_desc desc_local; desc_local.width = w; desc_local.height = h; desc_local.channels = (unsigned char)channels; desc_local.colorspace = (unsigned char)colorspace;
size_t px_count = (size_t)w * (size_t)h * (size_t)channels;
std::string pixels = FUZZ_PARAM_STR();
if (pixels.size() < px_count) { pixels.resize(px_count, '\0'); }
else if (pixels.size() > px_count) { pixels.resize(px_count); }
const char *path = FUZZ_PARAM_FILENAME();
int written = qoi_write(path, (const void*)pixels.data(), &desc_local);
if (written == 0) { FUZZ_BAIL(); }
// Choose channels parameter in {0,3,4}
int ch_sel_raw = (int)(*FUZZ_PARAM(unsigned int) % 3u);
int ch_param = (ch_sel_raw == 0) ? 0 : ((ch_sel_raw == 1) ? 3 : 4);
qoi_desc desc_out;
void *decoded_pixels = qoi_read(path, &desc_out, ch_param);
if (decoded_pixels) {
    // Validate required properties from the header
    FUZZ_ASSERT(desc_out.width > 0 && desc_out.height > 0, "qoi_read: positive dimensions expected");
    FUZZ_ASSERT(desc_out.channels == 3 || desc_out.channels == 4, "qoi_read: channels must be 3 or 4");
    FUZZ_ASSERT(desc_out.colorspace == 0 || desc_out.colorspace == 1, "qoi_read: colorspace must be 0 or 1");
    // Free the heap-allocated pixel buffer per API contract
    free(decoded_pixels);
}
// No outputs retained; all allocations freed.

// Build a valid qoi_desc and pixel buffer, then encode to QOI bytes
unsigned int channels = ((*FUZZ_PARAM(unsigned int)) & 1u) ? 3u : 4u;
unsigned int w = ((*FUZZ_PARAM(unsigned int)) % 64u) + 1u;
unsigned int h = ((*FUZZ_PARAM(unsigned int)) % 64u) + 1u;
unsigned int max_h_from_budget = 2048u / (w * channels);
if (max_h_from_budget == 0u) { max_h_from_budget = 1u; }
if (h > max_h_from_budget) { h = max_h_from_budget; }
unsigned int colorspace = ((*FUZZ_PARAM(unsigned int)) & 1u);
qoi_desc desc_local; desc_local.width = w; desc_local.height = h; desc_local.channels = (unsigned char)channels; desc_local.colorspace = (unsigned char)colorspace;
size_t px_count = (size_t)w * (size_t)h * (size_t)channels;
std::string pixels = FUZZ_PARAM_STR();
if (pixels.size() < px_count) { pixels.resize(px_count, '\0'); }
else if (pixels.size() > px_count) { pixels.resize(px_count); }
int out_len = 0;
void *encoded = qoi_encode((const void*)pixels.data(), (const qoi_desc*)&desc_local, &out_len);
if (encoded) {
    FUZZ_ASSERT(out_len > 0, "qoi_encode: successful encode must set out_len > 0");
    free(encoded);
}
// On failure, encoded==NULL and out_len is unmodified per API; nothing to free.

// Produce a valid QOI byte stream via qoi_encode, then decode it
// Step 1: create a small valid raw image
unsigned int channels = ((*FUZZ_PARAM(unsigned int)) & 1u) ? 3u : 4u;
unsigned int w = ((*FUZZ_PARAM(unsigned int)) % 32u) + 1u;
unsigned int h = ((*FUZZ_PARAM(unsigned int)) % 32u) + 1u;
unsigned int max_h_from_budget = 2048u / (w * channels);
if (max_h_from_budget == 0u) { max_h_from_budget = 1u; }
if (h > max_h_from_budget) { h = max_h_from_budget; }
unsigned int colorspace = ((*FUZZ_PARAM(unsigned int)) & 1u);
qoi_desc src_desc; src_desc.width = w; src_desc.height = h; src_desc.channels = (unsigned char)channels; src_desc.colorspace = (unsigned char)colorspace;
size_t px_count = (size_t)w * (size_t)h * (size_t)channels;
std::string pixels = FUZZ_PARAM_STR();
if (pixels.size() < px_count) { pixels.resize(px_count, '\0'); }
else if (pixels.size() > px_count) { pixels.resize(px_count); }
// Step 2: encode
int enc_len = 0;
void *enc_buf = qoi_encode((const void*)pixels.data(), (const qoi_desc*)&src_desc, &enc_len);
if (!enc_buf) { FUZZ_BAIL(); }
FUZZ_ASSERT(enc_len >= 22, "qoi_decode: encoded size should be >= header+end marker");
// Step 3: decode with channels in {0,3,4}
int ch_sel_raw = (int)(*FUZZ_PARAM(unsigned int) % 3u);
int ch_param = (ch_sel_raw == 0) ? 0 : ((ch_sel_raw == 1) ? 3 : 4);
qoi_desc out_desc;
void *decoded = qoi_decode((const void*)enc_buf, enc_len, &out_desc, ch_param);
if (decoded) {
    FUZZ_ASSERT(out_desc.width > 0 && out_desc.height > 0, "qoi_decode: positive dimensions expected");
    FUZZ_ASSERT(out_desc.channels == 3 || out_desc.channels == 4, "qoi_decode: channels must be 3 or 4");
    FUZZ_ASSERT(out_desc.colorspace == 0 || out_desc.colorspace == 1, "qoi_decode: colorspace must be 0 or 1");
    free(decoded);
}
free(enc_buf);

